INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p1", "partName": "Administrative Hierarchy under Asafjahi Rule", "bodyMd": "*   Nizam-ul-Mulk Asafjah separated the Deccan from the Mughal Empire, ruling under his own centralized control while nominally retaining regard for the Mughals.\n*   Appointed Mansabdars without Mughal consent — his own Mansabdars were called **\"Aasifias\"**.\n*   His heirs did not continue Mughal traditions.\n*   Capital shifted from **Aurangabad to Hyderabad in 1764**.\n*   **1724–1762**: internal conflicts among heirs shaped State formation.\n*   **1762–1803**: **Nizam Ali Khan''s** reign brought internal stability — expansion of forts, army, and administrative buildings.\n*   The resulting upper administrative class was called **Stately Officers (Prabhuvargam)**.\n\n### Jagirdari System\n\n*   **Jagir** meant a right ensuring permanent income through land — the practice of honoring persons for army-related service.\n*   One-third of the State was held as Jagirs.\n*   Big landlords (**Jagirdars**) collected taxes independently, with civic and judicial powers.\n*   Upper-level rulers'' council: **Umra-E-Ajam**.\n*   No uniform classification of ranks — due to (1) lack of standard classification and (2) heredity-based ownership.\n*   Standing depended on: (1) military service/relation with Nizam, (2) court reputation.\n*   Under Mohammedan rule, Jagir = owning landed property (also called **Inam, Altamshoo, Madaa-e-Maash**).\n\n**Threefold division of Hyderabad land:**\n\n| Division | Description |\n|---|---|\n| Jagirdari | Land-owning/non-land-owning, held by Stately Officers |\n| Sarfekhaas | Lands belonging to the King (Nizam) |\n| Dewani | Government lands |\n\n*   Jagirdari + Sarfekhaas = held by Stately Officers; Dewani formed two-thirds of total land.\n*   Stately Officers'' land, four parts: **Sarfekhaas, Pygah** (maintaining King''s forces), **Jagirs**, **Samsthanams** (pre-Nizam Hindu kingdoms/feudatories).\n\n**Social hierarchy (highest to lowest):** King → Pygah nobles → Umar-E-Ajam/Samsthanaadheeswaras (Stately Officers) → Jagirdars (big/middle/small) → I & II class Govt. employees → III class employees/traders → IV class employees/labourers.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p2", "partName": "Zamindars", "bodyMd": "*   Hereditary position; held titles like **Raja, Maharaja, Deshmukh, Sardar, Nawab, Reddy, Chowdhury**.\n*   Collected taxes, kept peasants under control; some held independent/sovereign status in their Jagirs.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p3", "partName": "Vatandars", "bodyMd": "*   **Vatandari**: cultivator-as-landowner system (Bhookamatamu), ancient, held by local landowners: **Patels, Patwaris, Deshmukhs, Sardeshmukhs, Deshpandes, Sardeshpandes**.\n*   Under **Salaar Jung''s** revenue reforms, Patels/Patwaris got land titles (**Pattas**) and cash pay.\n*   **Deshmukhs and Deshpandes** were the revenue authorities of the Paraganas (provinces).\n*   After the **Zilaabandi system**, Paragana authorities lost these responsibilities and land grants.\n*   **Rusum-e-Zamindari**: 5% (Deshmukhs) + 2½% (Deshpandes) of collected taxes, paid as hereditary service fee.\n*   **''Omlis''**: fixed taxes regardless of actual collection (mainly Karnataka region); 2/3 went to Government.\n*   **''Sera''/''savaram''**: free land grants to Deshmukhs/Deshpandes for service.\n*   **Reddys**: high-pedigreed landowners, also called Deshmukhs, Deshpandes, or **''Dora''/''Desai''**; British employed them as tax collectors and soldiers.\n*   **Raj Bahadur Venkat Ram Reddy**: first Hindu Kotwal of Hyderabad (1920s), served 14 years.\n*   Zamindars who fought against the Nizam (armed struggle from **1946**): **Ravi Narayana Reddy, Laxmi Narayana Reddy, Kodanda Rami Reddy, Baddam Ella Reddy**.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p4", "partName": "Village Devidies — Gadis of Zamindars", "bodyMd": "*   **Gadi** (Fort) — term confined to Telangana; built of sand and lime; Zamindars held court there with family.\n*   Doras kept horses (some used cars); joint family system; village Zamindars also called **Jagirdars/Maktedars**.\n*   Icons of village Doras: **Nawab Salar Jung, Maharaja Kishan Parshad, Nawab Kamal Jung**.\n*   Lack of education → unbridled Patel/Patwari authority; **Karanams** (addressed as \"Patwaris\") held complete land-holding knowledge.\n*   **95% of Deshmukhs were Reddys; 95% of Deshpandes were Brahmins** — yet no matrimonial ties between the groups.\n*   **Zamindars wielded more authority than the Kings.**", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p5", "partName": "Society — Caste System", "bodyMd": "*   Hyderabad was religiously/culturally mixed — **\"Ganga Jamuna Tehjeeb\"**.\n*   **1881 census**: 90.32% Hindu, 9.40% Muslim, 0.09% Christian, 0.08% Jain, 0.06% Parsi, 0.0031% Sikh, 47 Jews.\n*   By **1911 census**, Hindu % decreased, Muslim % increased in the city overall, but villages stayed more Hindu.\n*   Caste order: **Brahmins → Kshatriyas → Vaishyas → Shudras** (originally 4, expanded to hundreds).\n\n**Brahmins**: Two branches — Dravida, Gowda; by practice — Vaishnavas (Vishnu), Smarthas (Shiva); by occupation — **Vaidika** (priests/astrologers, poor) and **Niyogi** (army/agriculture/business; became **Karanams**, Sub Collectors, Translators under British).\n\n**Kshatriyas**: Second position; wore sacred threads; observed purdah; branches — Surya, Chandra, Matsya Vamsha; shifted to agriculture.\n\n**Vaishyas**: Third position; commerce/trade; **Komatis** in Andhra/Telangana; also money-lending; vegetarians.\n\n**Shudras**: Fourth, majority population; agriculture; many occupational sub-castes.\n\n**Caste-by-occupation table:**\n\n| Class | Castes |\n|---|---|\n| Agricultural | Kapu, Reddy, Velama, Kamma |\n| Animal-tending | Golla, Jalagari, Besta, Boya |\n| Panchannam vaaru | Vadrangi, Gayadla, Pinjaari, Chitrakarulu, Jogata, Netavaru, Salevaru, Vannegallu |\n| Trading | Komati, Balija, Telaga, Perika, Gandlavaaru |\n| Service | Chakali, Mangali, Katika, Katipapala, Medara, Idiga, Talari, Masti, Jetti, Chatri, Charma Karulu |\n| Poojari | Brahmins, Jangalu, Lingayats, Janagalu, Jogulu, Jatadharulu |\n| Dependent | Picchakuntla, Bhavanas, Runjulu, Pambalulu, Budabukkalu, Bhattu, Chandala, Maatangulu, Kommuri Dasas, Taviri Dasas, Suddulu |\n| Entertaining | Dommari, Bhogamvaaru, Vipra vinodulu, Aindrajaalikulu, Bommalaatala vaaru |\n| Avadhoota | Paramahamsas, Sanyasulu, Satani, Sivasattulu, Tambala, Yogulu, Jaina, Veera mushti, Kaleparasulu |\n| Asprusyulu | Mala, Madiga, Adihindu, Maliar, Mehatar, Chambaar, Mochi |\n| Girijanulu (Tribal) | Chenchu, Boya, Yaanadi, Gond, Pavara, Koli, Erukala, Lambadi, Bhil, Koya, Kondaredlu |\n| Videseeyulu (Foreign) | Parangulu, Ingileesulu, Paraasulu, Turaka, Odde, Gurjapu, Gowda, Mesra |\n\n**Key caste notes:**\n\n*   **Kapus/Reddys**: cultivating landowners; sub-sects Patangi, Motati, Udati, Pedakanti, Aare, Kamma, Velama, Konda, Aadi, Gona, Konidi.\n*   **Velamas**: North Indian immigrant origin; leaders called **Samasthanaadeswaras**.\n*   **Kammas**: agriculturists, claim Kshatriya status; women observe Ghosha.\n*   **Panchanamvaaru** (Vishwakarma lineage): Vadrangi (carpenter), Kamsaali (goldsmith — most important), Kasevaru (sculptor), Kammarulu (iron), Kancharulu (brass).\n*   **Kummari**: potters; village elders (Ayagars).\n*   **Salevaru** (weavers): sub-castes — Devanga, Togata, Padmasaali (weaving), Pattusaali (silk), Devangas (cotton), Togata (zari); deity Yellamma/Renukamaata.\n*   **Mangali (Barber)**: called **Nayee Brahmins**; women did midwifery, men surgery.\n*   **Gollas**: animal husbandry, also known as Yadavas.\n*   **Idiga/Goundla**: toddy extraction, low social rung.\n*   **Telagas**: soldiers under Golconda/Qutub Shahi rulers, called Batroths; till 1870 mostly worked as Deshmukh troops.\n*   **Asprusyulu (Untouchables)**: Parahaa caste, 5th position; lived outside villages.\n*   **Mala**: agricultural labourers; ate meat, didn''t visit Hindu temples.\n*   **Madiga**: hide-cleaning/chappal-making.\n*   **Adivasis**: Chenchus (villages), Koyas (forests) — Koya language; 6th category.\n*   **Gonds**: warrior class, Adilabad forests, ruled **1240–1750**.\n*   **Erukalu**: known for robbery/crime; women (Erukala Saanulu) did divination.\n*   **Lambadies (''Sugle''/''Banjaras'')**: migrated from Rajasthan, sold salt.\n*   **Balotadars**: village servants (priest, carpenter, blacksmith, potter, washerman, barber, Madiga, Mala) paid in paddy (\"Balota\") for service; included Karanam, Patel.\n*   **Muslims**: arrived 14th century; Shia/Sunni; foreign-origin called **''Afaakies''**, local called **''Deccanis''**; mostly army/administration/commerce.\n*   **Dodekula caste**: Hindu-to-Islam converts, spoke Telugu.\n*   **Europeans**: traded from Machilipatnam, Yanam, Ganjam, Narsapur, Kakinada.\n*   **Looso Indians**: Portuguese-Deccan hybrid race.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p6", "partName": "Condition of Women", "bodyMd": "*   Hyderabad: 6th-biggest princely state, 17 million population; culture called **''Ganga Jamuna Tehjeeb''**.\n*   Women''s condition studied in **three phases**: (1) first Nizam to 19th century, (2) intermediate reform period, (3) 20th century.\n\n**Phase 1** (worst period, till Salar Jung I''s appointment as PM):\n\n*   Women confined to four walls; even royal/rich women lacked individual liberty.\n*   Outside this norm: **Ayahs, Dayaas** (harem servants), **Tawaifs** (dancers — NOT prostitutes, respected artistes), and **Harlots** (practiced prostitution, socially disrespected).\n*   Nizam maintained Tawaifs via office **''Daftar-e-Arab Nishat''**, spending **Rs. 11,000** on salaries.\n*   **Purdah** was rampant among pedigreed families; unmarried daughters of the Nizam were exempt.\n\n**Notable women (Phase 1):**\n\n*   **Qairunnisa Begum**: married British Resident **Kirkpatrick**; Nizam adopted Kirkpatrick as son, title **''Hashmat Jung Bahadur''**; residency built became **Govt. Women''s College**.\n*   **Mahalakha Chandabai** (b.1766): first Urdu poetess of India; title **''Umrao''**; pen name **Chanda**; poems published 1824 as **''Guljar-e-Mahalakha''**; 125 Ghazals preserved in British Museum; died in the **1824 famine**.\n\n**Phase 2** (**1853–1883**): **Salar Jung** as PM; first Primary School for girls started; reduction in child marriages; seeds of women''s education sown.\n\n**Prominent women (18th–20th c.) — key facts:**\n\n*   **Sowgra Humayun Mirza** (b.1882): founded **Anjuman-E-Khavaateen Deccan**; started Safdaria Girls School.\n*   **Tayyaba Begum Sahiba Bilgrami** (b.1873): **first woman in India to get a B.A. degree** (1910, Madras University).\n*   **Tayyaba Begum**: founded first **Arts & Crafts School** and first **Domestic Science College** in Hyderabad.\n*   **Sarojini Naidu** (b.1879): \"**Bul-bul-E-Hind**\"; wrote _The Golden Threshold_, _The Bird of Time_; President of INC (Kanpur, 1925); **Kaizar-E-Hind medal**; Governor of West Bengal post-independence; fought purdah and child marriage; poem **''Tears of Asaf''** on Musi floods.\n\n**Women''s education milestones:**\n\n*   **1907**: Janana school for Muslim girls started (Sixth Nizam); **79 schools by 1930**.\n*   **1898**: **''Tahajib-un-Nisan''** paper by Sayyed Mumtaz Ali & Mohammadi Begum.\n*   **1904**: **''Khatoon''** paper by Sheik Abdullah Hadis & Jahana Begum, Aligarh.\n*   **Mir Osman Ali Khan** (25-year rule): established **677 primary, 28 middle, 4 special training schools**.\n*   **1938**: Domestic Science syllabus introduced for women.\n*   **Madapati Hanumantha Rao**: started a Girls School in Narayanaguda.\n\n**Women in Independence Movement (key names & roles):**\n\n*   **Jnana Kumari Heda**: first Satyagrahi from Hyderabad State.\n*   **T. Varalakshmamma**: President, 2nd Andhra Mahila Sabha; started Women Health Education Parishad.\n*   **Nadimpalli Sundaramma**: founded **Andhra Sodari Samajam (1915)**.\n*   **Arutla Kamaladevi**: first woman opposition leader of a State (Deputy Leader, Communist Party, 1962).\n*   **Sangem Lakshmibayamma**: only woman jailed for the National movement; first-generation Telangana graduate; later Lok Sabha member from Medak.\n\n**Organizations:**\n\n*   First women''s society: **Bharata Mahila Samajam (1907)**.\n*   **Andhra Sodari Samajam (1925)**, **Andhra Mahila Sabha (1930)**, **Andhra Yuvati Mandali (1935)**.\n\n**Prominent Ladies (key facts only):**\n\n*   **Princess Durru Shevar**: last Ottoman heir; established Hyderabad''s first Airport, Osmania General Hospital.\n*   **Nilofeur**: last Ottoman princess; built Nilofeur Hospital; did not observe purdah.\n*   **Masuma Begum**: **first Muslim lady to become a Minister in India** (1960).", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p7", "partName": "Social Evils and Bad Practices", "bodyMd": "Main evils: **bonded-labour, bagela, begari, illiteracy, child marriages, polygamy, dowry, purdah, Jogini system, prostitution.**\n\n### Bonded Labour\n\n*   Confined to tribals/backward castes in theory, but rampant across Telangana society.\n*   Harijan families forced to spare a member for unpaid service to Patel, Patwari, Karanam, Deshmukhs.\n*   Numerous free-service obligations: toddy, cloth, tools, washing, transport, food, and — most heinous — sending girls into service at landlord weddings.\n*   **Jagirdars, Zamindars, Paigahs, Samsthanaadheeswaras** collected ~**Rs. 10 crores** in illegal taxes (State''s lawful revenue before 1940 was ~**Rs. 8 crores**).\n*   Example: **Visunoor Ramchandrareddy** (Deshmukh, Janagaon) controlled bonded labour across ~40 villages.\n*   **Armed struggle in Telangana began in 1946** due to such excesses.\n*   **Mir Osman Ali Khan prohibited Begar in 1911**; law helped end bonded labour only with 20th-century education/reform.\n\n### Bagela\n\n*   Peasant unable to pay taxes became a bonded servant of the landlord.\n*   Prevalent in **Nalgonda and Warangal** districts.\n*   Debt passed to heirs if unpaid in lifetime.\n*   **Abolished by Nizam Government in 1930.**\n\n### Begari\n\n*   Forced unpaid labour, in vogue since ancient times, in towns and villages alike.\n*   **1911**: Osman Ali Khan''s farmana to abolish — ineffective.\n*   **1922 Farmana**: wages fixed (12 seers paddy/men, 8/women, 6/childre' WHERE chapter_slug = 'telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule';
UPDATE theory_content SET concepts_json = concepts_json || 'n); children under 10 exempted.\n*   **Abolished with Nizam''s merger into Indian Union, 1948.**\n\n### Child Marriages\n\n*   More common among Hindus (especially Brahmins) than Muslims; none among Christians.\n*   Caused: poverty, illiteracy; led to health issues/early death.\n*   **1899**: Age of Consent for Marriage Act.\n*   **Sarada Act, 1930**: abolished child marriage.\n\n### Widow Marriages\n\n*   Common in lower castes, rare in upper castes; Nizam State had **4x more widows than widowers**.\n*   **Widow Remarriage Act, 1856** — never enforced.\n*   **Salar Jung** married a widow, setting an example.\n\n### Polygamy\n\n*   Muslim Shariat permitted up to **4 wives**; upper-caste Hindu men also practiced it. Women could not remarry.\n*   Declined due to social reform and 20th-century Government efforts.\n\n### Dowry\n\n*   **Varasulkam** (dowry to bridegroom''s family) more common in Telangana than **Kanyasulkam** (dowry to bride''s family).\n*   Most prevalent among **Reddys and Velamas**; still continues today.\n\n### Devadasi–Jogini System\n\n*   Temple girls dedicated to God (Devadasis), later exploited by landlords — evolved into the **Jogini system**, mainly in North Telangana.\n*   Abolished due to reform efforts (Raghupati Venkata Ramiah Naidu in Andhra; Andhra Maha Sabha/Yuvati Mandali in Telangana).\n\n### Aadapapa\n\n*   Girls kept as bonded slaves/concubines by rulers and Zamindars, mostly in lower castes; children also became Aadapapas.\n\n### Prostitution\n\n*   Encouraged by Nawabs/rulers; performers called **''Tawaiffs''**.\n*   Office: **''Daftar-E-Nishan Kanchen Kacheris''**; supervisor titled **''Mamasharifa''**.\n*   This Tawaif system was **unique to Telangana, not found in Andhra**.\n\n### Purdah\n\n*   Spread from North India by Muslims; adopted by Hindu elites too.\n*   Entered Telangana **during Qutub Shahi period**, continued under Asafjahis.\n*   Survives today mainly in Muslim families.\n\n* * *\n\n# Land Tenures and Land Revenue Systems during Asafjahi Rule\n\nLand Tenures and Land Revenue Systems during Asafjahi Rule — as Hyderabad State was essentially agriculture-based, land ownership shaped both livelihoods and social standing.  \n\n*   **68% of population** depended on agriculture; land ownership = social status marker.\n*   Land revenue formed **50.29% of total tax revenue** (1933–34).\n\n### Land Classification\n\n1.  **Diwani/Khalsa lands** — direct Govt. administration; **54.8%** of State''s 82,698 sq. miles.\n2.  **Non-Khalsa lands** (**45.2%**) — (a) **Sarf-I-Khas** (Nizam''s privy purse), (b) **Jagir/Inam** grants.\n\n**Table: Types of Land Tenures**\n\n| Diwani/Khalsa | Other Khalsa Tenures | Non-Khalsa |\n|---|---|---|\n| Ryotwari (Pattedari, Pot-Pattedari, Shikmidari, Asami Shikmi) | Pan-Maqta; Tahud/Sarbasta; Ijara; Agrahar | Sarf-I-Khas; Samsthan/Peshkash; Jagir (Paigah, Al-Tamgha, Zat, Tankha, Mashrooti, Madad Mash); Inam |\n\n*   **Ryotwari tenure** (Bombay-system based): most important — over **50% of area**, more than **20 million acres**.\n*   Pattedar keeps land as long as revenue paid; evictable only for public purpose with compensation.\n\n### Cultivating Tenures & Tenants\n\n*   **Pattedari**: simple occupancy (self/hired cultivation).\n*   **Pot-Pattedari**: joint-stock cultivation, equal rights, not much in vogue.\n*   **Shikmidari**: land handed to cultivators (Shikmidars) under agreement — protected tenants.\n*   **Asami-Shikmi**: tenants-at-will; became Shikmidar after 12 years'' continuous occupation.\n*   Most leases (**75%**) were oral, tenancies-at-will terminated yearly — landlords avoided written agreements to prevent tenant rights.\n*   **Committee (1940) → Asami-Shikmi Act (1945)** → operative 1947 — recognized 6-year continuous occupants (1933–43) as protected tenants; poorly implemented.\n*   Non-Ryotwari tenures (Jagir, Maqta, Ijara, Agrahar, Inam) had even worse tenant conditions — cultivators of up to **90 years'' standing** still treated as tenants-at-will.\n*   **1,137 of 5,800 non-Diwani villages** remained unsurveyed by 1949, enabling record manipulation by landlords.\n*   **Hyderabad Tenancy and Agricultural Lands Act, 10 June 1950** — finally secured tenant rights (implemented post-1950).\n\n### Other Khalsa Tenures\n\n*   **Pan-Maqta**: contract tenure, fixed quit-rent, permanent/life grants; Maqtedars behaved like Jagirdars, manipulating records via Patel/Patwari posts they held.\n*   **Tahud/Sarbasta/Watandari**: tax-farming system; **abolished by Salar Jung I in 1866**. Ex-tax-farmers (Deshmukhs/Deshpandyas) compensated with land, strengthening their position.\n    *   **Rusum-i-zamindari**: hereditary pension = **7½%** of revenue (5% Deshmukhs, 2½% Deshpandyas), no service required.\n    *   Village-level Watandars: Patels, Patwaris, Talari, Sethsindhi, Neredu, Dhein.\n*   **Ijara** (1878): land-development lease, light rates rising to full assessment over **5–40 years**; abolished **1909 (1318 Fasli)**.\n*   **Agrahara**: quit-rent tenure for religious institutions; in practice, absentee landlordism and exploitation like other tenures.\n\n### Sarf-I-Khas\n\n*   **10% of Dominions**, spread over 18 Taluqs; Nizam''s privy purse; administered by Diwani officials under **Sadar-ul-Moham**.\n*   Miserly spending on welfare/irrigation despite good revenue collection; low staff salaries.\n*   **Taken over by Government in February 1949.**\n\n### Paigahs\n\n*   **''Paigah''** = Persian for stable/cavalry; also **Jamiat Jagirs**; created by **Nizam Ali Khan (1761–1803)** as counter-balancing military force after Minister **Rukhnuddaula''s** death (1775).\n*   Over **1,000 villages**, 2,000+ sq. miles, across 237 Taluqs, 10 Districts; none in Nalgonda (poor soil/irrigation).\n*   Full internal administrative/judicial control; **Reilly Commission (1927)** recommended disbanding — Nizam''s **1929 Firman** rejected this.\n\n### Jagirs\n\n*   Introduced by **Nizam-ul-mulk**; 1/3rd of territory distributed to nobles (Muslims: military; Hindus: administration).\n*   Types: **Al-tamgha** (revenue-free, permanent), **Zat** (unconditional maintenance grant), **Mashrooti** (service-conditional), **Madadmash** (gratuity/supplement), **Tankha** (pre-1853 salary substitute, redeemed by **Salar Jung I in 1853**).\n*   **Exempted Jagirdars**: big Jagirdars; **222 in Medak Suba alone** — ran private governments (own courts, police, revenue, survey depts.) — \"State within a State.\"\n*   **Non-exempted Jagirs**: smaller, e.g., 531 in Medak Suba; paid **Haq-e-malikana royalty (2–25%)**.\n*   Jagirdars collected **25–50% more revenue** than Khalsa villages; extracted **nazarana** before granting Pattedari rights.\n*   **35 types of illegal cesses** existed (e.g., Shadi-Patti/marriage tax, Ghar-Patti/house tax, Mohtarfa/handloom tax, grazing fines).\n*   **Vetti** (forced labour) was the most-hated practice — banned by Firman **1926**, ignored in practice.\n*   Jagir administration neglected education (75% villages had no primary school) and health/irrigation.\n*   Popular anger against Jagirdars fueled the **Peasants'' Armed Struggle (1946–51)**.\n\n### Inams\n\n*   ''Inam'' (Arabic: favour/reward) — revenue-free/partial land grant for service, charity, or reward; often hereditary.\n*   **Balota Inams**: 1/4th assessment, for village service.\n*   **Inam Commission (1865–1912)** — validated/resumed fraudulent grants.\n*   Total Inamdars: **83,000** (57,000 Diwani, 28,000 Jagir).\n*   **Circular No.4, 1298 Fasli (1889)**: allowed Inamdars to legally occupy excess land — worsened land concentration.\n\n### Samsthanas\n\n*   **''Peshkash''**: fixed annual tribute paid by conquered rulers/chiefs in exchange for self-administration.\n*   Only **3 true Peshkash Guzars**: **Gadwal (Rs.86,540), Anagundi (Rs.10,000), Gurgunta (Rs.7,050)**.\n*   Pan-Maqta-style Peshkash payers: **Wanaparti, Gopalpet, Jatpol, Bhadrachalam**.\n\n| Ruler | Peshkash |\n|---|---|\n| Wanaparti | Rs.83,862 |\n| Jatpol | Rs.71,944 |\n| Gopalpet | Rs.22,663 |\n| Bhadrachalam | Rs.45,875 |\n| **Total** | **Rs.2,13,844** |\n\n*   **14 Samsthanas** total; only **5 exempted** from Diwani jurisdiction — 3 of these (**Gadwal, Wanaparti, Jatpol**) from Mahaboobnagar District.\n*   Unlike scattered Jagirs, Samsthanas were **compact territorial units**, with own Police/Judicial systems and revenue surplus.\n*   Some Samsthandars — **Raja Rameshwar Rao of Wanaparti (d.1922)**, **Raja Venkat Lachman Rao Bahadur of Jatpole (d.1929)** — were benevolent, modernizing rulers.\n\n### Survey and Settlement\n\n*   **Survey and Settlement Department established 1875** (post tax-farming abolition by Salar Jung I).\n*   Bombay system adopted, adapted: Telangana rice areas assessed high in wet years, remitted in failure years (unlike Bombay''s flat rate).\n*   **Ayacut** (irrigable area) rule allowed corrupt over-classification as \"wet land\" — corrected only in **September 1949**.\n*   Work began: **1899 (1298 Fasli)** in Medak/Nizamabad Taluqs; **1915–16** in Mahaboobnagar.\n*   Settlement period: originally 30 years, reduced to **15 years** for Telangana.\n*   **Record of Rights Act (1936)** — flawed, recognized only nominal Pattedars; replaced by a **new Act in 1949** recognizing actual land holders.\n\n### Land Revenue Assessments\n\n**Table: Rate of Assessment (1912–1945), Rs-Annas-Paisa**\n\n| Division | Before 1912 Dry/Wet | 1912–22 Dry/Wet | 1934 Dry/Wet | 1945 Dry/Wet |\n|---|---|---|---|---|\n| Marathwada | 0-13-10 / 5-0-9 | 1-0-1 / 5-8-4 | 1-1-11 / 5-15-5 | 1-2-2 / 9-12-3 |\n| Telangana | 0-11-11 / 11-1-3 | 0-12-5 / 11-6-7 | 1-0-8 / 12-3-6 | 0-14-2 / 12-5-3 |\n| **State Avg.** | 0-12-10 / 8-1-0 | 0-14-3 / 8-7-5 | 1-0-8 / 9-1-6 | 1-0-7 / 11-2-0 |\n\n*   Assessment rates rose steadily 1912–1945; **dry land assessment higher in Marathwada, wet land assessment higher in Telangana**.\n*   Telangana wet rate (Medak Suba: **Rs.23-0-0/acre**) was 3x higher than Madras State (**Rs.7-1-6**).\n*   **S.M. Bharucha (1936–37 study)**: on a 16-acre farm, land revenue (Rs.30) was 9.4% of net yield (Rs.320), leaving little margin after other costs.\n*   **50% extra rate** charged on tank-irrigated double-crop lands, discouraging second cropping.\n*   **Mr. O''Connor** (Nizam''s Govt.) suggested a **25–30% reduction** in land revenue — never implemented.\n\n### Rents\n\n*   **1901–1911**: rent-receivers increased **1,748.8%** — landlords shifted from owner-farming to renting out.\n*   **Cash rents**: 40% of leased land (mainly dry land); risk borne by tenant; rents were **2–3x assessment rates** (tenants effectively paid 4–6x assessment).\n*   **Batai** (crop-sharing, 50-50): mainly for wet lands; risk shared between landlord and tenant.\n*   Rent burden: **35–45%** of produce (tank-irrigated), **25–30%** (well-irrigated), **15–40%** (dry, food vs cash crops).\n*   **Famine Commission (1901)**: noted tenants had sunk to the condition of \"mere serfs.\"\n\n### Remissions\n\n**Table: Remission Sub-heads, 1324 Fasli (1914–15)**\n\n| Head | Marathwada % | Telangana % | Total % |\n|---|---|---|---|\n| Water excess/deficit | 0.8 | 35.5 | 36.3 |\n| Breach of irrigation sources | 1.2 | 20.2 | 21.4 |\n| Submergence before cultivation | 0.1 | 5.8 | 5.9 |\n| Talaf Mal (crop failure) | 0.0 | 0.8 | 0.8 |\n| Change of crop/irrigation | 0.2 | 19.3 | 19.5 |\n| Double-crop cash remission | 0.5 | 8.8 | 9.3 |\n| Other | 0.7 | 6.1 | 6.8 |\n| **Total** | **3.5** | **96.5** | **100.0** |\n\n*   Telangana got **96.5% of remissions** (wet/chalka soils); Marathwada only 3.5% (dry black-soil tracts).\n*   Remissions mostly benefited **wet lands only**, and mainly wells built before **1908/1915** — corrected only in 1949.\n*   In practice, remissions rarely helped actual cultivators — officials extracted \"mamuls\" (bribes) to process claims; big landlords benefited most.\n*   **Sarf-I-Khas and Jagir villages** were denied remissions in practice, despite Government orders.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule-p8", "partName": "Summary", "bodyMd": "Land tenures and revenue administration in Hyderabad State were dominated by feudal, hereditary, authoritarian power groups (**Deshmukhs, Deshpandyas, Patels, Patwaris, Maqtedars, Agraharaiks, Paighas, Jagirdars, Samsthandars**). \n\nDiwani and non-Diwani tenures differed only in degree, not kind — both featured high assessments, rack-renting, forced/free labour (vetti), and remission systems that mainly benefited big landlords. Education, health, and infrastructure development in non-Diwani areas were minimal, with no channel for popular grievance redressal — conditions that fed directly into the **Telangana Peasants'' Armed Struggle (1946–51)**.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter17-social-conditions-and-land-revenue-systems-asafjahi-rule';
